package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
	"time"
)

var (
	uploadDir  = "/tmp/uploads"
	processMu  sync.Mutex
	allowedExt = map[string]bool{".png": true, ".jpg": true, ".gif": true, ".pdf": true}
)

func generateID() string {
	b := make([]byte, 16)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func sanitizeFilename(name string) string {
	// Remove path traversal attempts
	name = filepath.Base(name)
	// Remove null bytes
	name = strings.ReplaceAll(name, "\x00", "")
	return name
}

func validateExtension(filename string) bool {
	ext := strings.ToLower(filepath.Ext(filename))
	return allowedExt[ext]
}

func handleUpload(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, 10<<20) // 10MB limit

	file, header, err := r.FormFile("document")
	if err != nil {
		http.Error(w, "Failed to read file", 400)
		return
	}
	defer file.Close()

	origName := sanitizeFilename(header.Filename)
	if !validateExtension(origName) {
		http.Error(w, "File type not allowed", 400)
		return
	}

	fileID := generateID()
	dstPath := filepath.Join(uploadDir, fileID+"_"+origName)

	dst, err := os.Create(dstPath)
	if err != nil {
		http.Error(w, "Failed to save file", 500)
		return
	}
	defer dst.Close()

	if _, err := io.Copy(dst, file); err != nil {
		http.Error(w, "Failed to write file", 500)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"id":"%s","filename":"%s","status":"uploaded"}`, fileID, origName)
}

func handleConvert(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	fileID := r.FormValue("id")
	format := r.FormValue("format")

	if fileID == "" || format == "" {
		http.Error(w, "Missing parameters", 400)
		return
	}

	// Find the file by ID prefix
	entries, _ := os.ReadDir(uploadDir)
	var srcPath string
	for _, e := range entries {
		if strings.HasPrefix(e.Name(), fileID+"_") {
			srcPath = filepath.Join(uploadDir, e.Name())
			break
		}
	}

	if srcPath == "" {
		http.Error(w, "File not found", 404)
		return
	}

	// Validate format parameter - allow common formats
	validFormats := []string{"png", "jpg", "gif", "pdf", "webp", "tiff"}
	formatValid := false
	for _, vf := range validFormats {
		if strings.EqualFold(format, vf) {
			formatValid = true
			break
		}
	}
	if !formatValid {
		http.Error(w, "Invalid format", 400)
		return
	}

	outPath := srcPath + ".converted." + format

	processMu.Lock()
	defer processMu.Unlock()

	// Use ImageMagick to convert - the format is validated above
	// but the source filename (origName) was user-controlled
	cmdStr := fmt.Sprintf("convert %s %s", srcPath, outPath)
	cmd := exec.Command("sh", "-c", cmdStr)
	cmd.Env = append(os.Environ(), "MAGICK_TMPDIR=/tmp/magick")

	output, err := cmd.CombinedOutput()
	if err != nil {
		http.Error(w, fmt.Sprintf("Conversion failed: %s", string(output)), 500)
		return
	}

	// Serve the converted file
	w.Header().Set("Content-Disposition", fmt.Sprintf("attachment; filename=converted.%s", format))
	http.ServeFile(w, r, outPath)

	// Cleanup after serving
	go func() {
		time.Sleep(5 * time.Second)
		os.Remove(outPath)
	}()
}

func main() {
	os.MkdirAll(uploadDir, 0755)
	os.MkdirAll("/tmp/magick", 0755)

	http.HandleFunc("/upload", handleUpload)
	http.HandleFunc("/convert", handleConvert)
	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte("ok"))
	})

	fmt.Println("Server starting on :8080")
	http.ListenAndServe(":8080", nil)
}
